create table public.fx_observations(id uuid primary key default gen_random_uuid(),base_currency text not null,quote_currency text not null,rate numeric(24,10) not null check(rate>0),effective_at timestamptz not null,observed_at timestamptz not null,available_at timestamptz not null,provider text not null,source_reference text not null,data_quality smallint not null check(data_quality between 0 and 100),created_at timestamptz not null default now(),unique(provider,source_reference),check(effective_at<=observed_at),check(observed_at<=available_at));create index fx_lookup_idx on public.fx_observations(base_currency,quote_currency,effective_at desc,available_at);create or replace function public.prevent_fx_mutation()returns trigger language plpgsql as $$begin raise exception'FX observations are immutable';end$$;create trigger fx_observations_immutable before update or delete on public.fx_observations for each row execute function public.prevent_fx_mutation();alter table public.fx_observations enable row level security;create policy "public read fx" on public.fx_observations for select using(true);grant select on public.fx_observations to anon,authenticated;grant all on public.fx_observations to service_role;alter table public.ingestion_runs drop constraint if exists ingestion_runs_job_kind_check;alter table public.ingestion_runs add constraint ingestion_runs_job_kind_check check(job_kind in('stock_quotes','wallet_transactions','wallet_discovery','crypto_market','wallet_pnl','wallet_evidence','fast_flow','wallet_clustering','jackpot_collector','jackpot_outcomes','market_events','paper_eligibility','paper_execution','paper_exits','paper_valuation','performance','fx'));
